mapper.select:
select
mn.* from Sec_Project mn
left join Sec_Info sec on sec.Sec_Id=mn.Sec_Id left join Sec_Work_Schema ws on ws.Sec_Id=sec.Sec_Id where ws.id=#{id}

select sec.Sec_Name as secName, sec.Sec_Type as secType, sec.Sec_Organize_Form as secOrganizeForm, sec.Sec_Bidding_Type as secBiddingType, sec.Sec_Start_Time as secStartTime, sec.Sec_Bidding_Cycle as secBiddingCycle, sec.Sec_Place as secPlace, sec.Sec_Other_Valuation as secOtherValuation, sec.Sec_Pricing_Method as secPricingMethod, sec.Sec_Trading_Place as secTradingPlace, sec.Sec_Money as secMoney, sec.Sec_Contracting_department as secContractingDepartment, sec.Sec_Section_Classify as secSectionClassify, c4.C_Name as tendereeName, c6.C_Name as secAgencyName, case when pre.P_Name is null then sp.P_Name else pre.P_Name end as pName, case when pre.P_Category is null then sp.p_Category else pre.P_Category end as pCategory, case when pre.P_Build_Model is null then sp.P_Build_Model else pre.P_Build_Model end as pBuildModel, case when dpre.D_Name is null then sp.D_Name else dpre.D_Name end as pCompetentDepartmentName, mn.*, case when mn.P_Id is null then sp.P_ID else mn.P_Id end as projectId, case when mn.P_Id is null then sp.P_Id else mn.P_Id end as pId from Sec_Work_Schema mn left join Sec_Info sec on sec.Sec_Id=mn.Sec_Id left join pre_project pre on pre.P_Id=mn.P_Id left join SYS_Company c4 on c4.C_ID=sec.Sec_Tenderee left join Sys_Company c6 on c6.C_Id=sec.Sec_Agency left join SYS_Department dpre on dpre.D_Id = pre.p_Competent_Department left join Sys_File sf on sf.FileId=mn.id left join Sec_Bidding_Plan sbp on sbp.Bp_Id=sec.Bp_Id left join ( select sp1.Sec_Id, sp1.P_ID, pro1.P_Name, pro1.p_Category, pro1.P_Build_Model, dpre1.D_Name from Sec_Project sp1 inner join pre_project pro1 on pro1.P_Id = sp1.P_Id left join SYS_Department dpre1 on dpre1.D_Id = pro1.p_Competent_Department where not exists ( select 1 from Sec_Project sp2 inner join pre_project pro2 on pro2.P_Id = sp2.P_Id where sp2.Sec_Id = sp1.Sec_Id and pro2.P_Create_Time > pro1.P_Create_Time )) sp on sp.Sec_Id = mn.Sec_Id ${authSql}
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Create_Time desc
